(6153238, 907879, 108069, '<td valign="top">Wow. Great capture. Beautiful sky and great line, with the road leading the eyes to the bolt. Excellent.</td>', 'Wow. Great capture. Beautiful sky and great line, with the road leading the eyes to the bolt. Excellent.', '2010-09-06 08:42:41.000000', NULL, 1),
