(6155688, 907812, 37252, '<td valign="top">Cute portrait. While I do not see an s-curve that leads me through the image, it sure is technically sound otherwise.</td>', 'Cute portrait. While I do not see an s-curve that leads me through the image, it sure is technically sound otherwise.', '2010-09-08 02:02:28.000000', NULL, 1),
(6155691, 907766, 37252, '<td valign="top">With this being advanced editing I think you could have brought out the path more to emphasize the s-curve that forms the trail.</td>', 'With this being advanced editing I think you could have brought out the path more to emphasize the s-curve that forms the trail.', '2010-09-08 02:03:57.000000', NULL, 1),
(6155692, 907877, 120754, '<td valign="top">Subject is great.  It is leading and thought provoking.  I like the lighting from light with the subject to dark as it leads upward.</td>', 'Subject is great.  It is leading and thought provoking.  I like the lighting from light with the subject to dark as it leads upward.', '2010-09-08 02:05:07.000000', NULL, 1),
(6155695, 907881, 37252, '<td valign="top">I think the snake along - without the distraction of the hand would have worked better. I enjoy reptile and amphibian shots, but especially when they appear to be in a naturalistic environment.</td>', 'I think the snake along - without the distraction of the hand would have worked better. I enjoy reptile and amphibian shots, but especially when they appear to be in a naturalistic environment.', '2010-09-08 02:05:50.000000', NULL, 1),
(6155696, 907768, 37252, '<td valign="top">Nice lighting and composition</td>', 'Nice lighting and composition', '2010-09-08 02:06:12.000000', NULL, 1),
(6155700, 907542, 37252, '<td valign="top">I like the composition, angle shot, natural lighting and all - but wish the people were either not there at all, or if they have to be there that they were there in their entirety. It bothers me with the heads cut off the parents.</td>', 'I like the composition, angle shot, natural lighting and all - but wish the people were either not there at all, or if they have to be there that they were there in their entirety. It bothers me with the heads cut off the parents.', '2010-09-08 02:09:30.000000', NULL, 1),
