(6156153, 907810, 80908, '<td valign="top">Great concept - but I think you needed to find a smoother driver! ;o) That was a bumpy ride.</td>', 'Great concept - but I think you needed to find a smoother driver! ;o) That was a bumpy ride.', '2010-09-08 10:44:48.000000', NULL, 1),
(6156156, 907542, 80908, '<td valign="top">I suspect that this is a marmite photo. I am not sure, but the change of POV from looking down (at the bench) at the bottom to looking across (the bench) at the top feels a bit odd.</td>', 'I suspect that this is a marmite photo. I am not sure, but the change of POV from looking down (at the bench) at the bottom to looking across (the bench) at the top feels a bit odd.', '2010-09-08 10:46:38.000000', NULL, 1),
(6156160, 907479, 80908, '<td valign="top">nice POV, and I love the wisps of cloud starting to appear, but the saturation, sharpness and contrast here is a little ''in my face'' for such a peaceful scene.</td>', 'nice POV, and I love the wisps of cloud starting to appear, but the saturation, sharpness and contrast here is a little ''in my face'' for such a peaceful scene.', '2010-09-08 10:47:36.000000', NULL, 1),
